//! FORM autocomplete uses known-value reflection, independently of control hints.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form><input id=area name=q value=Seed><textarea id=text>Text</textarea><select id=select><option>A</option></select></form><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://form-autocomplete.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn form_autocomplete_canonical_once_conversion_and_exact_raw_setter(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'autocomplete');if(!a||!a.enumerable||!a.configurable||a.get.name!=='get autocomplete'||a.set.name!=='set autocomplete'||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,'autocomplete')||x.autocomplete!=='on')throw 'canonical';var calls=0;x.autocomplete={toString:function(){calls++;return 'OfF';},valueOf:function(){throw 'wrong hint';}};if(calls!==1||x.autocomplete!=='off'||x.getAttributeNS(null,'autocomplete')!=='OfF')throw 'once exact setter';x.autocomplete='off\ud800';if(x.autocomplete!=='on'||x.getAttributeNS(null,'autocomplete')!=='off\ud800')throw 'raw invalid';"#);}
#[test]
fn form_autocomplete_known_values_do_not_trim_or_use_control_token_grammar(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('form');for(var pair of [['on','on'],['OFF','off'],['oFf','off'],['','on'],[' off ','on'],['\toff','on'],['off\n','on'],['email','on'],['webauthn','on'],['section-x off','on'],['off on','on'],['unknown','on']]){x.setAttribute('autocomplete',pair[0]);if(x.autocomplete!==pair[1]||x.getAttributeNS(null,'autocomplete')!==pair[0])throw 'known value';}x.removeAttribute('autocomplete');if(x.autocomplete!=='on')throw 'missing default';x.autocomplete='off';if(document.getElementById('area').autocomplete!==''||document.getElementById('text').autocomplete!==''||document.getElementById('select').autocomplete!=='')throw 'form state leaked into control IDL';"#);}
#[test]
fn form_autocomplete_inert_namespace_raw_and_independent_copy(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=(new Document()).createElementNS('http://www.w3.org/1999/xhtml','form');x.setAttributeNS('urn:foreign','autocomplete','off');x.setAttributeNS(null,'AUTOCOMPLETE','off');if(x.autocomplete!=='on')throw 'namespace';x.autocomplete='oFf';var copy=x.cloneNode(false);copy.autocomplete='on';if(x.autocomplete!=='off'||copy.autocomplete!=='on'||copy.getAttributeNodeNS(null,'autocomplete')===x.getAttributeNodeNS(null,'autocomplete'))throw 'copy';x.autocomplete='\ud800';if(x.autocomplete!=='on'||x.getAttributeNS(null,'autocomplete')!=='\ud800')throw 'raw';"#);}

#[test]
fn form_autocomplete_authority_brands_and_abrupt_once_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),P=HTMLFormElement.prototype,a=Object.getOwnPropertyDescriptor(P,'autocomplete'),calls=0;for(var bad of [{},document,document.body,Object.create(P)]){try{a.set.call(bad,{toString:function(){calls++;return 'on';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}}if(calls)throw 'brand converted';x.autocomplete={toString:function(){calls++;x.autocomplete='off';return ' EMAIL ';}};if(calls!==1||x.autocomplete!=='on')throw 'outer conversion';var marker={};try{x.autocomplete={toString:function(){x.setAttribute('data-side','kept');throw marker;}};throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(x.autocomplete!=='on'||x.getAttribute('data-side')!=='kept')throw 'abrupt state';Object.defineProperty(P,'autocomplete',{get:function(){return 'author';},set:function(v){this.setAttribute('data-author',v);},configurable:true});x.autocomplete='override';a.set.call(x,'ON');if(x.autocomplete!=='author'||a.get.call(x)!=='on')throw 'saved authority';delete P.autocomplete;if(x.autocomplete!==undefined)throw 'hidden member';Object.defineProperty(P,'autocomplete',a);var C=HTMLFormElement;delete window.HTMLFormElement;if(!(x instanceof C)||a.get.call(x)!=='on')throw 'saved constructor';");}
#[test]
fn form_autocomplete_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLFormElement.prototype,'autocomplete'),calls=0;if(a.get.call(x)!=='on')throw 'same origin';");p.set_location(&crate::navigation::address("https://foreign-form-autocomplete.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'on';}});"]{p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);}p.set_location(&crate::navigation::address("https://form-autocomplete.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin converted';a.set.call(x,'ON');if(x.autocomplete!=='on')throw 'fresh recovery';");}

#[test]
fn form_autocomplete_named_control_precedence_preserves_saved_accessor_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),n=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLFormElement.prototype,'autocomplete');n.setAttribute('name','autocomplete');if(x.autocomplete!==n)throw 'named control precedence';var calls=0,watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});a.set.call(x,{toString:function(){calls++;return 'OFF';}});var records=watch.takeRecords();if(calls!==1||records.length!==1||records[0].attributeName!=='autocomplete'||x.autocomplete!==n||a.get.call(x)!=='off'||x.getAttributeNS(null,'autocomplete')!=='OFF')throw 'saved authority';a.set.call(x,'off\\ud800');if(a.get.call(x)!=='on'||x.getAttributeNS(null,'autocomplete')!=='off\\ud800')throw 'named raw setter';a.set.call(x,'OFF');n.setAttribute('name','q');if(x.autocomplete!=='off')throw 'live named removal';");}
#[test]
fn form_autocomplete_resource_refusal_is_atomic_and_fresh_job_recovers(){for getter in [false,true]{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form');x.autocomplete='off';");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("form")};let before=format!("{:?}",d.nodes);let retained=p.state.retained_limit;let string_limit=p.state.limits.host.string_bytes;let capture=(p.state.retained,p.state.dom_commits);p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2 if !getter=>p.state.retained_limit=p.state.retained,2=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let result=if getter{bridge.form_autocomplete_get(object).map(|_|())}else{bridge.form_autocomplete_set(object,&Value::String("growing-unknown-autocomplete-value".into()))};assert!(result.is_err(),"getter {getter} mode {mode}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),capture);p.state.retained_limit=retained;p.state.limits.host.string_bytes=string_limit;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x.autocomplete='ON';if(x.autocomplete!=='on'||document.getElementById('area').value!=='Seed')throw 'fresh recovery';");}}}
#[test]
fn form_autocomplete_attribute_writers_observe_raw_values_and_preserve_dirty_editor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('form'),editor=document.getElementById('area');editor.value='Edited';x.autocomplete='on';var attribute=x.getAttributeNodeNS(null,'autocomplete'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true,attributeFilter:['autocomplete']});");let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute('autocomplete','OFF');","x.setAttributeNS(null,'autocomplete','OFF');","attribute.value='OFF';","attribute.nodeValue='OFF';","attribute.textContent='OFF';"]{p.begin_job();run(&mut d,&mut f,&mut p,"x.autocomplete='on';watch.takeRecords();");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.autocomplete!=='off'||x.getAttributeNodeNS(null,'autocomplete')!==attribute||records.length!==1||records[0].oldValue!=='on'||records[0].attributeName!=='autocomplete'||editor.value!=='Edited')throw 'attribute observation';");let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}run(&mut d,&mut f,&mut p,r#"var replacement=document.createAttribute('autocomplete');replacement.value='off\ud800';x.setAttributeNodeNS(replacement);if(x.autocomplete!=='on'||attribute.ownerElement!==null||replacement.ownerElement!==x||replacement.value!=='off\ud800')throw 'raw attribute replacement';"#);}
